    resources: [{"title":"DeepLearning.AI Course Catalog","url":"https://www.deeplearning.ai/courses/","description":"The DeepLearning.AI catalog these lab notebooks are drawn from."},{"title":"aisuite (GitHub)","url":"https://github.com/andrewyng/aisuite","description":"The unified multi-provider LLM client used throughout these labs for chat completions and tool calling."}],
